#!/bin/sh
# NixOS on the Steam Link: %DESCRIPTION%
# Generated by nixos-steamlink (install-boot.sh); rewritten on every switch.
# The stock firmware runs this from the USB stick's FAT partition, mounted at /mnt/disk.
d=/mnt/disk/steamlink

# The stock bootloader factory-resets after too many boots it considers crashes.
fts-set steamlink.crashcounter 0

# FAT may be mounted noexec; fall back to a copy in RAM.
kexec=$d/kexec
[ -x "$kexec" ] || { cp "$kexec" /tmp/kexec && chmod 755 /tmp/kexec && kexec=/tmp/kexec; }

# A failed redirection would skip the commands, so only log where writing works.
log=$d/boot.log
: > "$log" || log=/tmp/steamlink-boot.log

{
  echo "booting %DESCRIPTION%"
  insmod "$d/kexec_load.ko"
  "$kexec" -l "$d/%KERNEL%" --dtb "$d/%DTB%" --command-line "%PARAMS%"
} >> "$log" 2>&1
sync
"$kexec" -e >> "$log" 2>&1
